INSERT INTO products (id, name, sku, description, category, price, specifications, industries, in_stock, image_url) VALUES
  ('00000000-0000-0000-0001-000000000001', 'AV-100 Ball Shut-Off Valve', 'AV-BV-SO-100', 'Precision ball shut-off valve for aviation fuel and hydraulic systems. Full bore design ensures maximum flow with minimal pressure drop.', 'Ball Valves', 1850.00, '{"pressureRating": "3000 PSI", "material": "Stainless Steel 316L", "connectionType": "AN Fittings", "temperature": "-65°F to +400°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/ball-shutoff.png'),
  ('00000000-0000-0000-0001-000000000002', 'AV-150 Ball Drain Valve', 'AV-BV-DR-150', 'Quick-action ball drain valve for fuel tank and sump applications. Features positive sealing and corrosion-resistant construction.', 'Ball Valves', 1250.00, '{"pressureRating": "1500 PSI", "material": "Aluminum 7075-T6", "connectionType": "MS Fittings", "temperature": "-65°F to +275°F"}', ARRAY['airplane', 'helicopter', 'drone']::industry_type[], true, '/valves/ball-drain.png'),
  ('00000000-0000-0000-0001-000000000003', 'AV-200 Flow Control Ball Valve', 'AV-BV-FC-200', 'Variable position ball valve for precise flow control in fuel metering and hydraulic systems.', 'Ball Valves', 2650.00, '{"pressureRating": "5000 PSI", "material": "Titanium Grade 5", "connectionType": "Flange Mount", "temperature": "-65°F to +450°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/ball-flow-control.png'),
  ('00000000-0000-0000-0001-000000000004', 'AV-250 Remote Motor Operated Valve', 'AV-BV-RMO-250', 'Electrically actuated ball valve with position feedback for remote operation. Ideal for fire suppression and fuel management systems.', 'Ball Valves', 4500.00, '{"pressureRating": "3000 PSI", "material": "Inconel 718", "connectionType": "SAE O-Ring Boss", "temperature": "-65°F to +600°F"}', ARRAY['airplane', 'helicopter']::industry_type[], false, '/valves/ball-motor-operated.png'),
  ('00000000-0000-0000-0001-000000000005', 'AV-300 Poppet Drain Valve', 'AV-DV-POP-300', 'Spring-loaded poppet style drain valve for fuel sumps and water drain applications. Push-to-drain operation.', 'Drain Valves', 650.00, '{"pressureRating": "500 PSI", "material": "Stainless Steel 303", "connectionType": "Threaded", "temperature": "-65°F to +250°F"}', ARRAY['airplane', 'helicopter', 'drone']::industry_type[], true, '/valves/drain-poppet.png'),
  ('00000000-0000-0000-0001-000000000006', 'AV-350 Solenoid Drain Valve', 'AV-DV-SOL-350', 'Electrically actuated solenoid drain valve for automated fuel management systems. Fail-safe normally closed design.', 'Drain Valves', 1450.00, '{"pressureRating": "1000 PSI", "material": "Aluminum Bronze", "connectionType": "AN Fittings", "temperature": "-40°F to +300°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/drain-solenoid.png'),
  ('00000000-0000-0000-0001-000000000007', 'AV-400 Float Arm Valve', 'AV-FV-ARM-400', 'Mechanical float arm style valve for fuel level control and overflow prevention in aircraft tanks.', 'Float Valves', 980.00, '{"pressureRating": "150 PSI", "material": "Stainless Steel 316", "connectionType": "Flange Mount", "temperature": "-65°F to +200°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/float-arm.png'),
  ('00000000-0000-0000-0001-000000000008', 'AV-450 Guided Float Valve', 'AV-FV-GF-450', 'Precision guided float valve for accurate fuel level control. Vertical mounting with anti-slosh design.', 'Float Valves', 1350.00, '{"pressureRating": "200 PSI", "material": "Titanium Grade 2", "connectionType": "MS Fittings", "temperature": "-65°F to +275°F"}', ARRAY['airplane', 'helicopter', 'drone']::industry_type[], true, '/valves/float-guided.png'),
  ('00000000-0000-0000-0001-000000000009', 'AV-500 Poppet Check Valve', 'AV-CV-POP-500', 'High-flow poppet style check valve for fuel and hydraulic systems. Low cracking pressure with positive sealing.', 'Check Valves', 1150.00, '{"pressureRating": "5000 PSI", "material": "Stainless Steel 17-4PH", "connectionType": "AN Fittings", "temperature": "-65°F to +400°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/check-poppet.png'),
  ('00000000-0000-0000-0001-000000000010', 'AV-550 Swing Check Valve', 'AV-CV-SW-550', 'Flapper style swing check valve for low-pressure fuel transfer systems. Lightweight design for weight-critical applications.', 'Check Valves', 890.00, '{"pressureRating": "1000 PSI", "material": "Aluminum 6061-T6", "connectionType": "Threaded", "temperature": "-65°F to +250°F"}', ARRAY['airplane', 'drone']::industry_type[], true, '/valves/check-swing.png'),
  ('00000000-0000-0000-0001-000000000011', 'AV-600 Split Butterfly Check Valve', 'AV-CV-SB-600', 'Dual-flapper split butterfly check valve for bi-directional sealing. Ideal for fuel crossfeed systems.', 'Check Valves', 1650.00, '{"pressureRating": "3000 PSI", "material": "Titanium Grade 5", "connectionType": "Flange Mount", "temperature": "-65°F to +450°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/check-butterfly.png'),
  ('00000000-0000-0000-0001-000000000012', 'AV-700 In-Line Pressure Vent', 'AV-PV-IL-700', 'In-line pressure/vacuum vent valve for fuel tank breathing. Prevents tank collapse and over-pressurization.', 'Pressure Vent Valves', 1250.00, '{"pressureRating": "50 PSI", "material": "Aluminum 7075-T6", "connectionType": "AN Fittings", "temperature": "-65°F to +275°F"}', ARRAY['airplane', 'helicopter', 'drone']::industry_type[], true, '/valves/vent-inline.png'),
  ('00000000-0000-0000-0001-000000000013', 'AV-750 Tank Mount Vent Valve', 'AV-PV-TM-750', 'Direct tank-mounted vent valve with ice protection. Maintains tank pressure equilibrium during altitude changes.', 'Pressure Vent Valves', 1850.00, '{"pressureRating": "75 PSI", "material": "Stainless Steel 316L", "connectionType": "Flange Mount", "temperature": "-65°F to +300°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/vent-tank.png'),
  ('00000000-0000-0000-0001-000000000014', 'AV-800 Hydraulic Regulator Valve', 'AV-HV-REG-800', 'Precision hydraulic pressure regulator for flight control systems. Maintains constant downstream pressure.', 'Hydraulic Valves', 3450.00, '{"pressureRating": "5000 PSI", "material": "Stainless Steel 17-4PH", "connectionType": "MS Fittings", "temperature": "-65°F to +275°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/hydraulic-regulator.png'),
  ('00000000-0000-0000-0001-000000000015', 'AV-850 Relief/Dump Valve', 'AV-HV-RD-850', 'Combination relief and dump valve for hydraulic system protection. Adjustable relief pressure with manual dump override.', 'Hydraulic Valves', 2850.00, '{"pressureRating": "6000 PSI", "material": "Titanium Grade 5", "connectionType": "SAE O-Ring Boss", "temperature": "-65°F to +400°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/hydraulic-relief.png'),
  ('00000000-0000-0000-0001-000000000016', 'AV-900 Hydraulic Control Valve', 'AV-HV-CTL-900', 'Multi-function hydraulic control valve for actuator systems. Proportional control with position feedback.', 'Hydraulic Valves', 5200.00, '{"pressureRating": "5000 PSI", "material": "Inconel 625", "connectionType": "Flange Mount", "temperature": "-65°F to +500°F"}', ARRAY['airplane', 'helicopter']::industry_type[], false, '/valves/hydraulic-control.png'),
  ('00000000-0000-0000-0001-000000000017', 'AV-1000 Gravity Fuel Fill Cap', 'AV-FC-GF-1000', 'Flush-mounted gravity fuel fill cap with vented design. Quick-release locking mechanism with fuel-resistant seals.', 'Fill Caps', 485.00, '{"pressureRating": "25 PSI", "material": "Aluminum 6061-T6", "connectionType": "Bayonet Mount", "temperature": "-65°F to +200°F"}', ARRAY['airplane', 'helicopter', 'drone']::industry_type[], true, '/valves/fillcap-fuel.png'),
  ('00000000-0000-0000-0001-000000000018', 'AV-1050 Gravity Oil Fill Cap', 'AV-FC-GO-1050', 'Engine oil fill cap with integrated dipstick provision. High-temperature resistant with positive locking.', 'Fill Caps', 325.00, '{"pressureRating": "15 PSI", "material": "Stainless Steel 303", "connectionType": "Threaded", "temperature": "-40°F to +400°F"}', ARRAY['airplane', 'helicopter']::industry_type[], true, '/valves/fillcap-oil.png'),
  ('00000000-0000-0000-0001-000000000019', 'Build to Print Service', 'AV-SVC-BTP', 'Custom manufacturing service for customer-supplied drawings and specifications. Full AS9100 quality system compliance.', 'Services', 0.00, '{"pressureRating": "Per Customer Spec", "material": "Per Customer Spec", "connectionType": "Per Customer Spec", "temperature": "Per Customer Spec"}', ARRAY['airplane', 'helicopter', 'drone']::industry_type[], true, '/valves/service-btp.png'),
  ('00000000-0000-0000-0001-000000000020', 'Build to Spec Service', 'AV-SVC-BTS', 'Custom valve design and manufacturing to customer performance specifications. Engineering support from concept to production.', 'Services', 0.00, '{"pressureRating": "Per Customer Spec", "material": "Per Customer Spec", "connectionType": "Per Customer Spec", "temperature": "Per Customer Spec"}', ARRAY['airplane', 'helicopter', 'drone']::industry_type[], true, '/valves/service-bts.png');
